"""生成图片识别评测用的参考文献图片（截图和模拟手机照片），并写出逐条标准答案。

用法：python eval/vision/generate.py
输出：eval/vision/out/*.png|jpg（不进仓库）和 eval/vision/cases.json（标准答案，进仓库）。
文献均为公开发表的真实论文和图书，字体使用 Windows 自带的 Arial、微软雅黑。
"""
import json
import random
from pathlib import Path

from PIL import Image, ImageDraw, ImageFilter, ImageFont

ROOT = Path(__file__).parent
OUT = ROOT / "out"
FONT_EN = "C:/Windows/Fonts/arial.ttf"
FONT_ZH = "C:/Windows/Fonts/msyh.ttc"

EN = [
    "[1] Walters, W. H., & Wilder, E. I. (2023). Fabrication and errors in the bibliographic citations generated by ChatGPT. Scientific Reports, 13, 14045. https://doi.org/10.1038/s41598-023-41032-5",
    "[2] LeCun, Y., Bengio, Y., & Hinton, G. (2015). Deep learning. Nature, 521(7553), 436–444.",
    "[3] K. He, X. Zhang, S. Ren, and J. Sun, \"Deep residual learning for image recognition,\" in Proc. IEEE Conf. Comput. Vis. Pattern Recognit. (CVPR), 2016, pp. 770–778.",
    "[4] Hochreiter, S., & Schmidhuber, J. (1997). Long short-term memory. Neural Computation, 9(8), 1735–1780.",
    "[5] Benjamini, Y., & Hochberg, Y. (1995). Controlling the false discovery rate: A practical and powerful approach to multiple testing. Journal of the Royal Statistical Society: Series B (Methodological), 57(1), 289–300.",
]
ZH = [
    "[1] 宫鹏, 牛振国, 程晓, 等. 中国1990和2000基准年湿地变化遥感[J]. 中国科学: 地球科学, 2010, 40(6): 768-775.",
    "[2] 廖宝文, 张乔民. 中国红树林的分布、面积和树种组成[J]. 湿地科学, 2014, 12(4): 435-440.",
    "[3] 王韦韦, 朱存玺, 陈黎卿. 玉米免耕播种机主动式秸秆移位防堵装置的设计与试验[J]. 农业工程学报, 2017, 33(24): 10-17.",
    "[4] 周志华. 机器学习[M]. 北京: 清华大学出版社, 2016.",
    "[5] 金旭杨. 基于深度学习的工程图像识别与分类研究[J]. 工程学研究与实用, 2025. DOI: 10.37155/2717-5316-0602-57.",
]


def wrap(draw: ImageDraw.ImageDraw, text: str, font: ImageFont.FreeTypeFont, width: int) -> list[str]:
    """按像素宽度换行；英文按词、中文按字。"""
    lines, current = [], ""
    # 不含汉字的条目按单词换行（真实排版不会在单词中间无连字符断开），含汉字的按字换行
    latin = not any("一" <= ch <= "鿿" for ch in text)
    tokens = text.split(" ") if latin else list(text)
    joiner = " " if latin else ""
    for token in tokens:
        trial = f"{current}{joiner}{token}" if current else token
        if draw.textlength(trial, font=font) <= width:
            current = trial
        else:
            lines.append(current)
            current = token
    if current:
        lines.append(current)
    return lines


def render(entries: list[str], font_path: str, size: int = 22, width: int = 1300, heading: str = "References") -> Image.Image:
    font = ImageFont.truetype(font_path, size)
    probe = ImageDraw.Draw(Image.new("RGB", (10, 10)))
    rows: list[str] = [heading, ""]
    for entry in entries:
        rows.extend(wrap(probe, entry, font, width - 80) + [""])
    line_height = int(size * 1.6)
    image = Image.new("RGB", (width, line_height * len(rows) + 80), "white")
    draw = ImageDraw.Draw(image)
    for i, row in enumerate(rows):
        draw.text((40, 40 + i * line_height), row, fill=(20, 20, 20), font=font)
    return image


def photo(image: Image.Image, seed: int = 7) -> Image.Image:
    """模拟手机拍照：纸张底色、轻微倾斜、模糊和噪点。"""
    rng = random.Random(seed)
    paper = Image.new("RGB", image.size, (236, 230, 214))
    mask = image.convert("L").point(lambda v: 255 if v < 200 else 0)
    paper.paste((40, 38, 36), mask=mask)
    tilted = paper.rotate(2.2, expand=True, fillcolor=(120, 115, 105))
    blurred = tilted.filter(ImageFilter.GaussianBlur(0.8))
    pixels = blurred.load()
    for _ in range(blurred.size[0] * blurred.size[1] // 12):
        x, y = rng.randrange(blurred.size[0]), rng.randrange(blurred.size[1])
        r, g, b = pixels[x, y]
        d = rng.randint(-25, 25)
        pixels[x, y] = (max(0, min(255, r + d)), max(0, min(255, g + d)), max(0, min(255, b + d)))
    return blurred


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    cases = []
    render(EN, FONT_EN).save(OUT / "en-screenshot.png")
    cases.append({"id": "en-screenshot", "file": "out/en-screenshot.png", "kind": "screenshot", "entries": EN})
    render(ZH, FONT_ZH, heading="参考文献").save(OUT / "zh-screenshot.png")
    cases.append({"id": "zh-screenshot", "file": "out/zh-screenshot.png", "kind": "screenshot", "entries": ZH})
    mixed = EN[:3] + ZH[:3]
    photo(render(mixed, FONT_ZH, size=24)).save(OUT / "mixed-photo.jpg", quality=72)
    cases.append({"id": "mixed-photo", "file": "out/mixed-photo.jpg", "kind": "photo", "entries": mixed})
    (ROOT / "cases.json").write_text(json.dumps({"description": "图片识别评测：每张图对应的逐条标准答案", "cases": cases}, ensure_ascii=False, indent=1), encoding="utf-8")
    print("\n".join(f"{c['id']}: {len(c['entries'])} 条" for c in cases))


if __name__ == "__main__":
    main()
